slug: arraypool-use-after-return
stack: dotnet
topic: performance
level: senior
type: find-bug
grading: auto
tags: [arraypool, pooling, buffers, ownership]
code:
  language: csharp
  harness: statements
  source: |
    using System.Buffers;

    int[] squares = Fill(4, i => i * i);
    int[] cubes = Fill(4, i => i * i * i);
    Console.WriteLine(string.Join(",", squares.Take(4)));
    Console.WriteLine(string.Join(",", cubes.Take(4)));

    static int[] Fill(int count, Func<int, int> f)
    {
        int[] buffer = ArrayPool<int>.Shared.Rent(count);
        try
        {
            for (int i = 0; i < count; i++)
            {
                buffer[i] = f(i + 1);
            }
            return buffer;
        }
        finally
        {
            ArrayPool<int>.Shared.Return(buffer);
        }
    }
bugLineSets: [[21]]
fixedSource: |
  using System.Buffers;

  int[] squares = ArrayPool<int>.Shared.Rent(4);
  int[] cubes = ArrayPool<int>.Shared.Rent(4);
  try
  {
      Fill(squares, 4, i => i * i);
      Fill(cubes, 4, i => i * i * i);
      Console.WriteLine(string.Join(",", squares.Take(4)));
      Console.WriteLine(string.Join(",", cubes.Take(4)));
  }
  finally
  {
      ArrayPool<int>.Shared.Return(cubes);
      ArrayPool<int>.Shared.Return(squares);
  }

  static void Fill(int[] buffer, int count, Func<int, int> f)
  {
      for (int i = 0; i < count; i++)
      {
          buffer[i] = f(i + 1);
      }
  }
fixedExpect: { kind: output, value: "1,4,9,16\n1,8,27,64" }
